const claim=$input.first().json;
const job=claim.job??{};
// The real queue claim returns job.metadata, not a top-level task.\nconst req=claim.task??job.metadata?.dispatch_task??job.metadata?.task??{};\nconst worker=String(claim.worker_id??'').trim();
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const CARD=/^https:\/\/trello\.com\/c\/[a-z0-9]+(?:\/[^\s]*)?$/i;
const RUN=/^AUTO-\d{8}-\d{4}$/;
const ok=claim.ok===true && claim.claimed===true && claim.protocol==="queue_run_v2";
const files=req.allowed_files??[];
const fileOK=p=>typeof p==='string'&&!p.includes('..')&&!p.includes('\\')
  &&(/^(ui|docs)\/[a-zA-Z0-9_.\/-]+$/.test(p))
  &&p!=="ui/config.js"&&!p.startsWith("docs/executable-cards/");
if(!ok||!UUID.test(String(job.id||""))||!UUID.test(String(claim.execution_run_id||"")))
 throw new Error("VERIFIED_QUEUE_V2_CLAIM_REQUIRED");
if(job.executor_key!=="github-actions-md")throw new Error("WRONG_EXECUTOR");\nif(!/^[a-zA-Z0-9_:-]{6,100}$/.test(worker))throw new Error("WORKER_ID_REQUIRED");
if(!CARD.test(job.card_url??"")||!RUN.test(req.run_key??""))
 throw new Error("REAL_CARD_AND_DAILY_RUN_REQUIRED");
if((claim.run_key&&claim.run_key!==req.run_key)||req.queue_id!==job.id||req.card_url!==job.card_url||req.project_key!=="memoria-duilio")
 throw new Error("CLAIM_PAYLOAD_MISMATCH");
if(typeof req.title!=="string"||!req.title.trim()||req.title.length>300||
 typeof req.problem!=="string"||!req.problem.trim()||req.problem.length>12000||
 !Array.isArray(files)||files.length<1||files.length>3||
 new Set(files).size!==files.length||!files.every(fileOK))
 throw new Error("BOUNDED_TASK_REQUIRED");
const criteria=req.acceptance_criteria??[];
if(!Array.isArray(criteria)||criteria.length>8||!criteria.every(s=>typeof s==='string'&&s.length<=400))
 throw new Error("INVALID_ACCEPTANCE_CRITERIA");
return [{json:{
  event_type:"md_propose",
  client_payload:{card_url:job.card_url,queue_id:job.id,run_key:req.run_key,
    title:req.title.trim(),problem:req.problem,allowed_files:files,acceptance_criteria:criteria,\n    execution_run_id:claim.execution_run_id,worker_id:worker},
  execution_run_id:claim.execution_run_id,
  status:"validated_pending_dispatch"
}}];

const response=$input.first().json??{};
const code=Number(response.statusCode??response.status??0);
if(code!==204){
  throw new Error("GITHUB_DISPATCH_UNCONFIRMED_"+(code||"NO_STATUS"));
}
const c=$("Validar claim y tarea acotada").first().json;
return [{json:{
  status:"dispatched_waiting_for_pr",dispatched:true,queue_id:c.client_payload.queue_id,
  card_url:c.client_payload.card_url,run_key:c.client_payload.run_key,
  execution_run_id:c.execution_run_id,
  note:"GitHub accepted event only. DO NOT mark queue completed or close Trello. Verify actual Actions run, PR, tests and CE-1."
}}];
